def digest(s): return hashlib.sha256(s.replace("\r\n","\n").encode("utf-8")).hexdigest()
def split(path):
 m=re.match(r"\A---\r?\n(.*?)\r?\n---\r?\n(.*)\Z",path.read_text(encoding="utf-8-sig"),re.S)
 if not m: raise ValueError(path)
 return m.group(1),m.group(2)
def fh(path): return digest(path.read_text(encoding="utf-8-sig"))
